mapper.select:
SELECT id, MATCH(search_terms) AGAINST (#{terms} IN NATURAL LANGUAGE MODE) AS score FROM knowledge_chunk WHERE enterprise_id = #{enterprise} AND (document_id, file_id, generation) IN
(#{version.id}, #{version.activeFileId}, #{version.activeGeneration})
AND MATCH(search_terms) AGAINST (#{terms} IN NATURAL LANGUAGE MODE) > 0 ORDER BY score DESC LIMIT #{limit}
